/// <reference types="@cloudflare/workers-types" />

// @ts-ignore .open-next/worker.js is generated by opennextjs-cloudflare build.
import openNextWorker from '../.open-next/worker.js'
import { runAuthorizedScheduledPublish } from './lib/scheduled-publish-orchestrator.js'

type InternalService = {
  fetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response>
}

type ScheduledEnv = {
  W03_CONTENT: InternalService
  W08_CREATOR: InternalService
}

const worker = {
  fetch: openNextWorker.fetch,

  async scheduled(controller: ScheduledController, env: ScheduledEnv): Promise<void> {
    if (controller.cron !== '* * * * *') return

    const scheduledAt = new Date(controller.scheduledTime).toISOString()
    try {
      const result = await runAuthorizedScheduledPublish(env)
      console.info(JSON.stringify({
        event: 'content.scheduled-publish',
        cron: controller.cron,
        scheduledTime: scheduledAt,
        ...result,
      }))
    } catch (error) {
      console.error(JSON.stringify({
        event: 'content.scheduled-publish.failed',
        cron: controller.cron,
        scheduledTime: scheduledAt,
        reason: error instanceof Error ? error.message.slice(0, 160) : 'UNKNOWN',
      }))
      throw error
    }
  },
}

// OpenNext's generated Worker owns HTTP fetch; this wrapper adds only cron.
export default worker
